import Link from 'next/link';
import status from './observatory-status.json';
import s from './ResearchExperience.module.css';

/** Generated by the dedicated public-source collector, refreshed through reviewed deployments. */
export default function CollectionStatus() {
  const date = new Date(status.last_capture_at).toLocaleString('en-GB', {
    day: '2-digit', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit', timeZone: 'UTC',
  });
  return <section className={s.collection} aria-label="Recorded collection status">
    <div><h2>Collection record</h2><p className={s.fine}>A real check of the collection pipeline, separate from the synthetic example below.</p></div>
    <dl><dt>Source</dt><dd><a href={status.source_url}>{status.source}</a></dd><dt>Last captured</dt><dd><time dateTime={status.last_capture_at}>{date} UTC</time></dd><dt>Forecasts</dt><dd>{status.pending} pending · {status.resolved} resolved · {status.expired} expired</dd><dt>Collection failures</dt><dd>{status.collection_failures}</dd><dt>Integrity check</dt><dd>{status.integrity}</dd></dl>
    <p className={s.fine}>Updated after scheduled collection and a reviewed site deployment. This is a recorded status, not a live connection. It uses the local clock and a constant 50% forecast of file-byte changes.</p>
    <Link className={s.secondary} href="/experiments/prospective-observatory">Collection and evaluation protocol</Link>
  </section>;
}
